$ErrorActionPreference = 'Stop'
if (-not (Test-Path 'package.json')) {
    Write-Host 'ERROR: run from project root.' -ForegroundColor Red
    exit 1
}

# Make sure shadcn dialog component is installed
Write-Host '-> Verifying dialog component (will be a no-op if already installed)' -ForegroundColor Cyan
if (-not (Test-Path 'components/ui/dialog.tsx')) {
    npx shadcn@latest add dialog -y --silent 2>$null
}

$files = @{}
$files['vercel.json'] = 'ewogICJjcm9ucyI6IFsKICAgIHsKICAgICAgInBhdGgiOiAiL2FwaS9jcm9uL3N5c3RlbS1ydWxlcyIsCiAgICAgICJzY2hlZHVsZSI6ICIwICogKiAqICoiCiAgICB9CiAgXQp9Cg=='
$files['app/api/cron/system-rules/route.ts'] = ''
$files['lib/system-rules/rules.ts'] = ''
$files['app/(app)/admin/actions.ts'] = ''
$files['app/(app)/admin/page.tsx'] = ''
$files['app/(app)/admin/_components/invite-user-dialog.tsx'] = ''
$files['app/auth/callback/route.ts'] = ''
$files['app/(app)/console/page.tsx'] = ''
$files['components/app/skeleton.tsx'] = ''
$files['app/(app)/dashboard/loading.tsx'] = ''
$files['app/(app)/accounts/loading.tsx'] = ''
$files['app/(app)/contacts/loading.tsx'] = ''
$files['app/(app)/deals/loading.tsx'] = ''
$files['app/(app)/error.tsx'] = ''
$files['app/not-found.tsx'] = ''
$files['app/(app)/dashboard/page.tsx'] = ''

Write-Host ''
Write-Host '-> Day 6: cron rules + admin invite + polish' -ForegroundColor Cyan
Write-Host '   (5 system rules, magic-link invites, console, skeletons, error pages)' -ForegroundColor DarkGray
Write-Host ''
foreach ($path in $files.Keys) {
    $content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($files[$path]))
    $dir = Split-Path -Parent $path
    if ($dir -and -not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    $fullPath = Join-Path -Path (Get-Location) -ChildPath $path
    [System.IO.File]::WriteAllText($fullPath, $content, [System.Text.UTF8Encoding]::new($false))
    Write-Host ('  + ' + $path) -ForegroundColor Green
}

Write-Host ''
Write-Host '====================================' -ForegroundColor Green
Write-Host '  Day 6 files written' -ForegroundColor Green
Write-Host '====================================' -ForegroundColor Green
Write-Host ''
Write-Host 'IMPORTANT - extra setup steps:' -ForegroundColor Yellow
Write-Host ''
Write-Host '1. Add CRON_SECRET env var to Vercel:' -ForegroundColor White
Write-Host '     Generate one: openssl rand -base64 32  (or any random string)' -ForegroundColor DarkGray
Write-Host '     Add to Vercel project Settings > Environment Variables' -ForegroundColor DarkGray
Write-Host '     Variable: CRON_SECRET (Sensitive, Production only)' -ForegroundColor DarkGray
Write-Host ''
Write-Host '2. Push to prod, then verify cron is registered:' -ForegroundColor White
Write-Host '     git add . ; git commit ; git push' -ForegroundColor DarkGray
Write-Host '     Visit Vercel project > Settings > Cron Jobs > should show /api/cron/system-rules' -ForegroundColor DarkGray
Write-Host ''
Write-Host '3. Test locally first:' -ForegroundColor White
Write-Host '     npm run dev' -ForegroundColor DarkGray
Write-Host '     http://localhost:3000/admin   (try Invite User button)' -ForegroundColor DarkGray
Write-Host '     http://localhost:3000/console (super_admin only - shows cron logs)' -ForegroundColor DarkGray
Write-Host ''